package db

import (
	"database/sql"
	"time"

	"github.com/lib/pq"
)

type Grocery struct {
	ID        int       `json:"id"`
	Name      string    `json:"name"`
	Quantity  int       `json:"quantity"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

func (db *DB) CreateGrocery(name string, quantity int) (*Grocery, error) {
	query := `
		INSERT INTO groceries (name, quantity)
		VALUES ($1, $2)
		RETURNING id, name, quantity, created_at, updated_at
	`
	var grocery Grocery
	err := db.QueryRow(query, name, quantity).Scan(
		&grocery.ID,
		&grocery.Name,
		&grocery.Quantity,
		&grocery.CreatedAt,
		&grocery.UpdatedAt,
	)
	if err != nil {
		return nil, err
	}
	return &grocery, nil
}

func (db *DB) GetGroceryByID(id int) (*Grocery, error) {
	query := `
		SELECT id, name, quantity, created_at, updated_at
		FROM groceries
		WHERE id = $1
	`
	var grocery Grocery
	err := db.QueryRow(query, id).Scan(
		&grocery.ID,
		&grocery.Name,
		&grocery.Quantity,
		&grocery.CreatedAt,
		&grocery.UpdatedAt,
	)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, ErrNotFound
		}
		return nil, err
	}
	return &grocery, nil
}

func (db *DB) ListGroceries() ([]*Grocery, error) {
	query := `
		SELECT id, name, quantity, created_at, updated_at
		FROM groceries
	`
	rows, err := db.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		var grocery Grocery
		err := rows.Scan(
			&grocery.ID,
			&grocery.Name,
			&grocery.Quantity,
			&grocery.CreatedAt,
			&grocery.UpdatedAt,
		)
		if err != nil {
			return nil, err
		}
		groceries = append(groceries, &grocery)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return groceries, nil
}

func (db *DB) UpdateGrocery(id int, name string, quantity int) (*Grocery, error) {
	query := `
		UPDATE groceries
		SET name = $1, quantity = $2, updated_at = NOW()
		WHERE id = $3
		RETURNING id, name, quantity, created_at, updated_at
	`
	var grocery Grocery
	err := db.QueryRow(query, name, quantity, id).Scan(
		&grocery.ID,
		&grocery.Name,
		&grocery.Quantity,
		&grocery.CreatedAt,
		&grocery.UpdatedAt,
	)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, ErrNotFound
		}
		return nil, err
	}
	return &grocery, nil
}

func (db *DB) DeleteGrocery(id int) error {
	query := `
		DELETE FROM groceries
		WHERE id = $1
	`
	_, err := db.Exec(query, id)
	if err != nil {
		if err == sql.ErrNoRows {
			return ErrNotFound
		}
		return err
	}
	return nil
}

