package handlers

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strconv"

	"github.com/gorilla/mux"
	"your-project/db"
)

// GroceryHandler handles grocery-related HTTP requests
func GroceryHandler(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id := vars["id"]

	switch r.Method {
	case http.MethodGet:
		if id == "" {
			// List all groceries
			groceries, err := db.GetGroceries(db.DB)
			if err != nil {
				http.Error(w, fmt.Sprintf("Error fetching groceries: %v", err), http.StatusInternalServerError)
				return
			}
			w.Header().Set("Content-Type", "application/json")
			json.NewEncoder(w).Encode(groceries)
		} else {
			// Get a single grocery by ID
			grocery, err := db.GetGroceryByID(db.DB, atoi(id))
			if err != nil {
				if err == db.ErrNoRows {
					http.Error(w, "Grocery not found", http.StatusNotFound)
					return
				}
				http.Error(w, fmt.Sprintf("Error fetching grocery: %v", err), http.StatusInternalServerError)
				return
			}
			if grocery == nil {
				http.Error(w, "Grocery not found", http.StatusNotFound)
				return
			}
			w.Header().Set("Content-Type", "application/json")
			json.NewEncoder(w).Encode(grocery)
		}
	case http.MethodPost:
		// Create a new grocery
		var req struct {
			Name      string `json:"name"`
			Quantity  int    `json:"quantity"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			http.Error(w, "Invalid JSON", http.StatusBadRequest)
			return
		}

		grocery, err := db.CreateGrocery(db.DB, req.Name, req.Quantity)
		if err != nil {
			http.Error(w, fmt.Sprintf("Error creating grocery: %v", err), http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(grocery)
	case http.MethodPut:
		// Update a grocery by ID
		if id == "" {
			http.Error(w, "ID required for update", http.StatusBadRequest)
			return
		}
		var req struct {
			Name      string `json:"name"`
			Quantity  int    `json:"quantity"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			http.Error(w, "Invalid JSON", http.StatusBadRequest)
			return
		}

		err := db.UpdateGrocery(db.DB, atoi(id), req.Name, req.Quantity)
		if err != nil {
			http.Error(w, fmt.Sprintf("Error updating grocery: %v", err), http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusOK)
		w.Write([]byte(`{"message": "Grocery updated successfully"}`))
	case http.MethodDelete:
		// Delete a grocery by ID
		if id == "" {
			http.Error(w, "ID required for deletion", http.StatusBadRequest)
			return
		}
		err := db.DeleteGrocery(db.DB, atoi(id))
		if err != nil {
			http.Error(w, fmt.Sprintf("Error deleting grocery: %v", err), http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusOK)
		w.Write([]byte(`{"message": "Grocery deleted successfully"}`))
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// atoi converts a string to int, returning 0 on error
func atoi(s string) int {
	i, err := strconv.Atoi(s)
	if err != nil {
		return 0
	}
	return i
}

