	"database/sql"
	"fmt"
	"time"

	"github.com/jmoiron/sqlx"
	_ "github.com/lib/pq"
)

// Grocery represents a grocery item
type Grocery struct {
	ID        int
	Name      string
	Quantity  int
	CreatedAt time.Time
	UpdatedAt time.Time
}

// GroceryDB provides operations for groceries
type GroceryDB struct {
	DB *sqlx.DB
}

// NewGroceryDB creates a new GroceryDB instance
func NewGroceryDB(db *sqlx.DB) *GroceryDB {
	return &GroceryDB{DB: db}
}

// List returns all groceries
func (g *GroceryDB) List() ([]Grocery, error) {
	var groceries []Grocery
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries ORDER BY id`
	rows, err := g.DB.Queryx(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	for rows.Next() {
		var grocery Grocery
		if err := rows.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt); err != nil {
			return nil, err
	} else {
			groceries = append(groceries, grocery)
		}
	}
	return groceries, nil
}

// Get returns a single grocery by ID
func (g *GroceryDB) Get(id int) (*Grocery, error) {
	var grocery Grocery
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1`
	err := g.DB.Get(&grocery, query, id)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, err
	}
	return &grocery, nil
}

// Create inserts a new grocery
func (g *GroceryDB) Create(name, quantity string) (*Grocery, error) {
	query := `INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id, name, quantity, created_at, updated_at`
	var grocery Grocery
	err := g.DB.Get(&grocery, query, name, quantity)
	if err != nil {
		return nil, err
	}
	return &grocery, nil
}

// Update updates an existing grocery
func (g *GroceryDB) Update(id int, name, quantity string) error {
	query := `UPDATE groceries SET name = $2, quantity = $3, updated_at = now() WHERE id = $1`
	_, err := g.DB.Exec(query, id, name, quantity)
	return err
}

// Delete removes a grocery by ID
func (g *GroceryDB) Delete(id int) error {
	query := `DELETE FROM groceries WHERE id = $1`
	_, err := g.DB.Exec(query, id)
	return err
}

