package db

import (
	"context"
	"database/sql"
	"errors"
	"time"

	"github.com/google/uuid"
	_ "github.com/lib/pq"
)

// Grocery represents a grocery item
type Grocery struct {
	ID        int
	Name      string
	Quantity  int
	CreatedAt time.Time
	UpdatedAt time.Time
}

// GroceryDB provides CRUD operations for groceries
type GroceryDB struct {
	db *sql.DB
}

// NewGroceryDB creates a new GroceryDB instance
func NewGroceryDB(db *sql.DB) *GroceryDB {
	return &GroceryDB{db: db}
}

// List retrieves all groceries
func (g *GroceryDB) List(ctx context.Context) ([]Grocery, error) {
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries ORDER BY id`
	rows, err := g.db.QueryContext(ctx, query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []Grocery
	for rows.Next() {
		var grocery Grocery
		if err := rows.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt); err != nil {
			return nil, err
		}
		groceries = append(groceries, grocery)
	}
	return groceries, nil
}

// Get retrieves a grocery by ID
func (g *GroceryDB) Get(ctx context.Context, id int) (*Grocery, error) {
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1`
	var grocery Grocery
	err := g.db.QueryRowContext(ctx, query, id).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, errors.New("grocery not found")
		}
		return nil, err
	}
	return &grocery, nil
}

// Create creates a new grocery
func (g *GroceryDB) Create(ctx context.Context, name string, quantity int) (*Grocery, error) {
	query := `INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id, name, quantity, created_at, updated_at`

	// Use UUID for id, but we're using integer primary key so we'll just insert and get the auto-generated ID
	// In this case, we're assuming the database uses auto-increment for id
	var grocery Grocery
	err := g.db.QueryRowContext(ctx, query, name, quantity).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &grocery, nil
}

// Update updates a grocery by ID
func (g *GroceryDB) Update(ctx context.Context, id int, name string, quantity int) (*Grocery, error) {
	query := `UPDATE groceries SET name = $2, quantity = $3, updated_at = NOW() WHERE id = $1 RETURNING id, name, quantity, created_at, updated_at`

	var grocery Grocery
	err := g.db.QueryRowContext(ctx, query, id, name, quantity).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, errors.New("grocery not found")
		}
		return nil, err
	}
	return &grocery, nil
}

// Delete deletes a grocery by ID
func (g *GroceryDB) Delete(ctx context.Context, id int) error {
	query := `DELETE FROM groceries WHERE id = $1`
	result, err := g.db.ExecContext(ctx, query, id)
	if err != nil {
		return err
	}
	if result.RowsAffected() == 0 {
		return errors.New("grocery not found")
	}
	return nil
}

