	groceryDB := db.NewGroceryDB(dbConn)

	// Create router
	r := mux.NewRouter()

	// Grocery routes
	groceryHandler := handlers.NewGroceryHandler(groceryDB)
	r.HandleFunc("/groceries", groceryHandler.List).Methods("GET")
	r.HandleFunc("/groceries/{id}", groceryHandler.Get).Methods("GET")
	r.HandleFunc("/groceries", groceryHandler.Create).Methods("POST")
	r.HandleFunc("/groceries/{id}", groceryHandler.Update).Methods("PUT")
	r.HandleFunc("/groceries/{id}", groceryHandler.Delete).Methods("DELETE")

	// Start server
	port := Port
	if port == "" {
		port = "8080"
	}
	fmt.Printf("Server is running on port %s\n", port)

	server := http.Server{
		Addr:    ":" + port,
		Handler: r,
	}

	// Graceful shutdown
	ctx, stop := context.WithCancel(context.Background())
	defer stop()

	go func() {
		<-ctx.Done()
		log.Println("Shutting down server...")
		server.Shutdown(context.Background())
	}()

	// Start server
	if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		log.Fatal("Server error:", err)
	}
}

