	UpdatedAt time.Time
}

// GetGroceries retrieves all groceries
func GetGroceries(db *sql.DB) ([]Grocery, error) {
	var groceries []Grocery
	rows, err := db.Query("SELECT id, name, quantity, created_at, updated_at FROM groceries ORDER BY id")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	for rows.Next() {
		var g Grocery
		if err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt); err != nil {
			return nil, err
		}
		groceries = append(groceries, g)
	}
	return groceries, nil
}

// GetGroceryByID retrieves a single grocery by ID
func GetGroceryByID(db *sql.DB, id int) (*Grocery, error) {
	var g Grocery
	row := db.QueryRow("SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1", id)
	if err := row.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt); err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, err
	}
	return &g, nil
}

// CreateGrocery creates a new grocery
func CreateGrocery(db *sql.DB, name string, quantity int) (int, error) {
	// Generate a new ID (in practice, this would be auto-incremented in the DB)
	id := getNewID()
	_, err := db.Exec("INSERT INTO groceries (id, name, quantity, created_at, updated_at) VALUES ($1, $2, $3, NOW(), NOW())", id, name, quantity)
	if err != nil {
		return 0, err
	}
	return id, nil
}

// UpdateGrocery updates an existing grocery
