package db

import (
	"context"
	"database/sql"
	"fmt"
	"log"
	"time"

	"github.com/your-org/your-app/pkg/db"
)

// Grocery represents a grocery item
type Grocery struct {
	ID        int
	Name      string
	Quantity  int
	CreatedAt time.Time
	UpdatedAt time.Time
}

// GetAll returns all groceries
func GetAll(ctx context.Context) ([]Grocery, error) {
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries ORDER BY id`
	rows, err := db.DB.QueryContext(ctx, query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []Grocery
	for rows.Next() {
		var g Grocery
		if err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt); err != nil {
			return nil, err
		}
		groceries = append(groceries, g)
	}
	return groceries, nil
}

// GetByID returns a grocery by ID
func GetByID(ctx context.Context, id int) (*Grocery, error) {
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1`
	var g Grocery
	err := db.DB.QueryRowContext(ctx, query, id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, err
	}
	return &g, nil
}

// Create inserts a new grocery
func Create(ctx context.Context, name string, quantity int) (*Grocery, error) {
	query := `INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id, name, quantity, created_at, updated_at`
	var g Grocery
	err := db.DB.QueryRowContext(ctx, query, name, quantity).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

// Update updates an existing grocery
func Update(ctx context.Context, id int, name string, quantity int) error {
	query := `UPDATE groceries SET name = $2, quantity = $3, updated_at = NOW() WHERE id = $1`
	_, err := db.DB.ExecContext(ctx, query, id, name, quantity)
	if err != nil {
		return err
	}
	return nil
}

// Delete removes a grocery by ID
func Delete(ctx context.Context, id int) error {
	query := `DELETE FROM groceries WHERE id = $1`
	_, err := db.DB.ExecContext(ctx, query, id)
	if err != nil {
		return err
	}
	return nil
}

