		VALUES ($1, $2) 
		RETURNING id, name, quantity, created_at, updated_at`

	// Set default quantity to 0 if not provided
	if quantity == 0 {
		quantity = 0
	}

	// Use a raw query to avoid potential SQL injection
	result := schema.DB.QueryRowContext(ctx, query, name, quantity)
	var g Grocery
	if err := result.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt); err != nil {
		return nil, fmt.Errorf("failed to create grocery: %w", err)
	}
	return &g, nil
}

// Update updates an existing grocery by ID
