	query := `
		UPDATE groceries 
		SET name = $2, quantity = $3, updated_at = NOW() 
		WHERE id = $1`
	_, err := schema.DB.ExecContext(ctx, query, id, name, quantity)
	if err != nil {
		return fmt.Errorf("failed to update grocery: %w", err)
	}
	return nil
}

// Delete removes a grocery by ID
