package db

import (
	"database/sql"
	"log"
	"time"

	"github.com/your-org/your-project/pkg/db"
)

// Grocery represents a grocery item
type Grocery struct {
	ID        int
	Name      string
	Quantity  int
	CreatedAt time.Time
	UpdatedAt time.Time
}

// GetGroceries retrieves all groceries
func GetGroceries(db *sql.DB) ([]Grocery, error) {
	var groceries []Grocery
	query := `
		SELECT id, name, quantity, created_at, updated_at 
		FROM groceries 
		ORDER BY id
	`
	rows, err := db.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	for rows.Next() {
		var g Grocery
		if err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt); err != nil {
			return nil, err
		}
		groceries = append(groceries, g)
	}

	return groceries, nil
}

// GetGroceryByID retrieves a grocery by ID
func GetGroceryByID(db *sql.DB, id int) (*Grocery, error) {
	var g Grocery
	query := `
		SELECT id, name, quantity, created_at, updated_at 
		FROM groceries 
		WHERE id = $1
	`
	err := db.QueryRow(query, id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil // 404
		}
		return nil, err
	}
	return &g, nil
}

// CreateGrocery creates a new grocery
func CreateGrocery(db *sql.DB, name string, quantity int) (*Grocery, error) {
	query := `
		INSERT INTO groceries (name, quantity) 
		VALUES ($1, $2) 
		RETURNING id, name, quantity, created_at, updated_at
	`
	var g Grocery
	err := db.QueryRow(query, name, quantity).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

// UpdateGrocery updates a grocery by ID
func UpdateGrocery(db *sql.DB, id int, name string, quantity int) error {
	query := `
		UPDATE groceries 
		SET name = $2, quantity = $3, updated_at = now() 
		WHERE id = $1
	`
	_, err := db.Exec(query, id, name, quantity)
	return err
}

// DeleteGrocery deletes a grocery by ID
func DeleteGrocery(db *sql.DB, id int) error {
	query := `
		DELETE FROM groceries 
		WHERE id = $1
	`
	_, err := db.Exec(query, id)
	return err
}

