package db

import (
	"context"
	"database/sql"
	"log"
	"time"

	"github.com/google/uuid"
)

type Grocery struct {
	ID        int
	Name      string
	Quantity  int
	CreatedAt time.Time
	UpdatedAt time.Time
}

func (g Grocery) TableName() string {
	return "groceries"
}

func GetGroceries(db *sql.DB) ([]Grocery, error) {
	var groceries []Grocery
	rows, err := db.QueryContext(context.Background(),
		`SELECT id, name, quantity, created_at, updated_at
		 FROM groceries ORDER BY id`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	for rows.Next() {
		var g Grocery
		if err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt); err != nil {
			return nil, err
		}
		groceries = append(groceries, g)
	}

	return groceries, nil
}

func GetGroceryByID(db *sql.DB, id int) (*Grocery, error) {
	var g Grocery
	row := db.QueryRowContext(context.Background(),
		`SELECT id, name, quantity, created_at, updated_at
		 FROM groceries WHERE id = $1`,
		id)
	if err := row.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt); err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, err
	}
	return &g, nil
}

func CreateGrocery(db *sql.DB, name, quantity string) (*Grocery, error) {
	id := uuid.New().Int()
	createdAt := time.Now()
	updatedAt := createdAt

	_, err := db.ExecContext(context.Background(),
		`INSERT INTO groceries (id, name, quantity, created_at, updated_at)
		 VALUES ($1, $2, $3, $4, $5)`,
		id, name, quantity, createdAt, updatedAt)
	if err != nil {
		return nil, err
	}

	return &Grocery{
		ID:        id,
		Name:      name,
		Quantity:  0,
		CreatedAt: createdAt,
		UpdatedAt: updatedAt,
	}, nil
}

func UpdateGrocery(db *sql.DB, id int, name, quantity string) error {
	_, err := db.ExecContext(context.Background(),
		`UPDATE groceries SET name = $2, quantity = $3, updated_at = $4
		 WHERE id = $1`,
		id, name, quantity, time.Now())
	if err != nil {
		return err
	}
	return nil
}

func DeleteGrocery(db *sql.DB, id int) error {
	_, err := db.ExecContext(context.Background(),
		`DELETE FROM groceries WHERE id = $1`,
		id)
	return err
}

