package db

import (
	"context"
	"log"
	"time"

	"github.com/ajstarks/svgo"
	"gorm.io/gorm"
)

type Grocery struct {
	ID        uint      `json:"id" gorm:"primary_key"`
	Name      string    `json:"name" gorm:"not null"`
	Quantity  int       `json:"quantity" gorm:"not null;default:0"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

// GetGrocery retrieves a grocery by ID
func GetGrocery(db *gorm.DB, id uint) (*Grocery, error) {
	var grocery Grocery
	err := db.Where("id = ?", id).First(&grocery).Error
	if err != nil {
		if err == gorm.ErrRecordNotFound {
			return nil, nil
		}
		return nil, err
	}
	return &grocery, nil
}

// ListGroceries retrieves all groceries
func ListGroceries(db *gorm.DB) ([]*Grocery, error) {
	var groceries []*Grocery
	err := db.Find(&groceries).Error
	if err != nil {
		return nil, err
	}
	return groceries, nil
}

// CreateGrocery creates a new grocery
func CreateGrocery(db *gorm.DB, name string, quantity int) (*Grocery, error) {
	grocery := Grocery{
		Name:      name,
		Quantity:  quantity,
		CreatedAt: time.Now(),
		UpdatedAt: time.Now(),
	}
	err := db.Create(&grocery).Error
	if err != nil {
		return nil, err
	}
	return &grocery, nil
}

// UpdateGrocery updates an existing grocery
func UpdateGrocery(db *gorm.DB, id uint, name string, quantity int) error {
	var grocery Grocery
	err := db.Where("id = ?", id).First(&grocery).Error
	if err != nil {
		if err == gorm.ErrRecordNotFound {
			return nil
	} else {
		return err
	}
	grocery.Name = name
	grocery.Quantity = quantity
	grocery.UpdatedAt = time.Now()
	return db.Save(&grocery).Error
}

// DeleteGrocery deletes a grocery by ID
func DeleteGrocery(db *gorm.DB, id uint) error {
	var grocery Grocery
	err := db.Where("id = ?", id).First(&grocery).Error
	if err != nil {
		if err == gorm.ErrRecordNotFound {
			return nil
		}
		return err
	}
	return db.Delete(&grocery, "id = ?", id).Error
