package db

import (
	"context"
	"database/sql"
	"fmt"
	"log"
	"time"

	"github.com/your-org/your-app/pkg/db"
)

// Grocery represents a grocery item
type Grocery struct {
	ID        int
	Name      string
	Quantity  int
	CreatedAt time.Time
	UpdatedAt time.Time
}

// GetGroceries retrieves all groceries
func GetGroceries(ctx context.Context) ([]Grocery, error) {
	var groceries []Grocery
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries ORDER BY id`
	rows, err := db.DB.QueryContext(ctx, query)
	if err != nil {
		return nil, fmt.Errorf("error querying groceries: %w", err)
	}
	defer rows.Close()

	for rows.Next() {
		var g Grocery
		if err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt); err != nil {
			return nil, fmt.Errorf("error scanning grocery: %w", err)
		}
		groceries = append(groceries, g)
	}

	return groceries, nil
}

// GetGroceryByID retrieves a single grocery by ID
func GetGroceryByID(ctx context.Context, id int) (*Grocery, error) {
	var g Grocery
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1`
	err := db.DB.QueryRowContext(ctx, query, id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, fmt.Errorf("error querying grocery by ID: %w", err)
	}
	return &g, nil
}

// CreateGrocery creates a new grocery
func CreateGrocery(ctx context.Context, name string, quantity int) (*Grocery, error) {
	query := `INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id, name, quantity, created_at, updated_at`
	var g Grocery
	err := db.DB.QueryRowContext(ctx, query, name, quantity).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return nil, fmt.Errorf("error creating grocery: %w", err)
	}
	return &g, nil
}

// UpdateGrocery updates an existing grocery
func UpdateGrocery(ctx context.Context, id int, name string, quantity int) (*Grocery, error) {
	query := `UPDATE groceries SET name = $2, quantity = $3, updated_at = now() WHERE id = $1 RETURNING id, name, quantity, created_at, updated_at`
	var g Grocery
	err := db.DB.QueryRowContext(ctx, query, id, name, quantity).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, fmt.Errorf("error updating grocery: %w", err)
	}
	return &g, nil
}

// DeleteGrocery deletes a grocery by ID
func DeleteGrocery(ctx context.Context, id int) error {
	query := `DELETE FROM groceries WHERE id = $1`
	result, err := db.DB.ExecContext(ctx, query, id)
	if err != nil {
		return fmt.Errorf("error deleting grocery: %w", err)
	}
	if result.RowsAffected() == 0 {
		return nil
	}
	return nil
}

