package db

import (
	"context"
	"database/sql"
	"fmt"
	"log"
	"time"

	"github.com/google/uuid"
)

// Grocery represents a grocery item with name and quantity
type Grocery struct {
	ID        int
	Name      string
	Quantity  int
	CreatedAt time.Time
	UpdatedAt time.Time
}

// GroceryDB provides database operations for groceries
type GroceryDB struct {
	DB *sql.DB
}

// NewGroceryDB creates a new GroceryDB instance
func NewGroceryDB(db *sql.DB) *GroceryDB {
	return &GroceryDB{DB: db}
}

// List returns all groceries
func (g *GroceryDB) List(ctx context.Context) ([]*Grocery, error) {
	query := `
		SELECT id, name, quantity, created_at, updated_at 
		FROM groceries 
		ORDER BY id
	`
	rows, err := g.DB.QueryContext(ctx, query)
	if err != nil {
		return nil, fmt.Errorf("failed to query groceries: %w", err)
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		var grocery Grocery
		if err := rows.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt); err != nil {
			return nil, fmt.Errorf("failed to scan grocery row: %w", err)
		}
		groceries = append(groceries, &grocery)
	}
	return groceries, nil
}

// Get returns a single grocery by ID
func (g *GroceryDB) Get(ctx context.Context, id int) (*Grocery, error) {
	query := `
		SELECT id, name, quantity, created_at, updated_at 
		FROM groceries 
		WHERE id = $1
	`
	var grocery Grocery
	err := g.DB.QueryRowContext(ctx, query, id).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, fmt.Errorf("failed to get grocery: %w", err)
	}
	return &grocery, nil
}

// Create inserts a new grocery
func (g *GroceryDB) Create(ctx context.Context, name string, quantity int) (*Grocery, error) {
	query := `
		INSERT INTO groceries (name, quantity) 
		VALUES ($1, $2) 
		RETURNING id, name, quantity, created_at, updated_at
	`
	var grocery Grocery
	err := g.DB.QueryRowContext(ctx, query, name, quantity).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		return nil, fmt.Errorf("failed to create grocery: %w", err)
	}
	return &grocery, nil
}

// Update modifies an existing grocery
func (g *GroceryDB) Update(ctx context.Context, id int, name string, quantity int) (*Grocery, error) {
	query := `
		UPDATE groceries 
		SET name = $2, quantity = $3, updated_at = now()
		WHERE id = $1
		RETURNING id, name, quantity, created_at, updated_at
	`
	var grocery Grocery
	err := g.DB.QueryRowContext(ctx, query, id, name, quantity).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, fmt.Errorf("failed to update grocery: %w", err)
	}
	return &grocery, nil
}

// Delete removes a grocery by ID
func (g *GroceryDB) Delete(ctx context.Context, id int) error {
	query := `
		DELETE FROM groceries 
		WHERE id = $1
	`
	result, err := g.DB.ExecContext(ctx, query, id)
	if err != nil {
		return fmt.Errorf("failed to delete grocery: %w", err)
	}
	if result.RowsAffected() == 0 {
		return nil
	}
	return nil
}

