	"gorm.io/gorm"
)

type Grocery struct {
	ID        uint      `json:"id" gorm:"primary_key"`
	Name      string    `json:"name" gorm:"not null"`
	Quantity  int       `json:"quantity" gorm:"not null;default:0"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

func (g Grocery) ToJSON() map[string]interface{} {
	return map[string]interface{}{
		"id":        g.ID,
		"name":      g.Name,
		"quantity":  g.Quantity,
		"created_at": g.CreatedAt,
		"updated_at": g.UpdatedAt,
	}
}

func (g *Grocery) FromJSON(data map[string]interface{}) error {
	if v, ok := data["name"]; ok {
		if s, ok := v.(string); ok {
			g.Name = s
		}
	}
	if v, ok := data["quantity"]; ok {
		if i, ok := v.(int); ok {
			g.Quantity = i
		}
	}
	return nil
}

func GetAllGroceries(db *gorm.DB) ([]Grocery, error) {
	var groceries []Grocery
	if err := db.Find(&groceries).Error; err != nil {
		return nil, err
	}
	return groceries, nil
}

func GetGroceryByID(db *gorm.DB, id uint) (*Grocery, error) {
	var grocery Grocery
	if err := db.First(&grocery, id).Error; err != nil {
		return nil, err
	}
	return &grocery, nil
}

func CreateGrocery(db *gorm.DB, grocery *Grocery) error {
	grocery.UpdatedAt = time.Now()
	return db.Create(grocery).Error
}

func UpdateGrocery(db *npgorm.DB, id uint, grocery *Grocery) error {
	grocery.UpdatedAt = time.Now()
	return db.Model(&Grocery{ID: id}).Updates(grocery).Error
}

func DeleteGrocery(db *gorm.DB, id uint) error {
	return db.Delete(&Grocery{}, id).Error
}

