	"strconv"

	"github.com/your-org/your-app/internal/db"
	"github.com/your-org/your-app/internal/middleware"
)

// ListGroceries returns a list of all groceries
func ListGroceries(w http.ResponseWriter, r *http.Request) {
	groceries, err := db.GetGroceries(r.Context())
	if err != nil {
		http.Error(w, fmt.Sprintf("Internal error: %v", err), http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(groceries)
}

// GetGrocery returns a single grocery by ID
func GetGrocery(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.URL.Query.Get("id"))
	if err != nil || id <= 0 {
		http.Error(w, "Invalid or missing ID", http.StatusBadRequest)
		return
	}

	grocery, err := db.GetGroceryByID(r.Context(), id)
	if err != nil {
		http.Error(w, fmt.Sprintf("Grocery not found: %v", err), http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(grocery)
}

// CreateGrocery creates a new grocery
func CreateGrocery(w http.ResponseWriter, r *http.Request) {
	var grocery struct {
		Name      string `json:"name"`
		Quantity  int    `json:"quantity"`
	}

	if err := json.NewDecoder(r.Body).Decode(&grocery); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	if grocery.Name == "" {
		http.Error(w, "Name is required", http.StatusBadRequest)
		return
	}

	groceryItem, err := db.CreateGrocery(r.Context(), grocery.Name, grocery.Quantity)
	if err != nil {
		http.Error(w, fmt.Sprintf("Failed to create grocery: %v", err), http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(groceryItem)
}

// UpdateGrocery updates an existing grocery
func UpdateGrocery(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.URL.Query.Get("id"))
	if err != nil || id <= 0 {
		http.Error(w, "Invalid or missing ID", http.StatusBadRequest)
		return
	}

	var grocery struct {
		Name      string `json:"name"`
		Quantity  int    `json:"quantity"`
	}

	if err := json.NewDecoder(r.Body).Decode(&grocery); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	if grocery.Name == "" {
		http.Error(w, "Name is required", http.StatusBadRequest)
		return
	}

	err = db.UpdateGrocery(r.Context(), id, grocery.Name, grocery.Quantity)
	if err != nil {
		http.Error(w, fmt.Sprintf("Failed to update grocery: %v", err), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
}

// DeleteGrocery deletes a grocery by ID
func DeleteGrocery(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.URL.Query.Get("id"))
	if err != nil || id <= 0 {
		http.Error(w, "Invalid or missing ID", http.StatusBadRequest)
		return
	}

