func (g *GroceryDB) Create(ctx context.Context, name string, quantity int) (*Grocery, error) {
	query := `
		INSERT INTO groceries (name, quantity) 
		VALUES ($1, $2) 
		RETURNING id, name, quantity, created_at, updated_at
	`
	row := g.db.QueryRowContext(ctx, query, name, quantity)
	var grocery Grocery
	if err := row.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt); err != nil {
