package db

import (
	"database/sql"
	"fmt"
	"time"

	"github.com/golang-migrate/migrate/v4"
	_ "github.com/lib/pq"
)

// Grocery represents a grocery item
type Grocery struct {
	ID        int
	Name      string
	Quantity  int
	CreatedAt time.Time
	UpdatedAt time.Time
}

// DB handles database operations for groceries
type DB struct {
	*sql.DB
}

// NewGroceryDB initializes a new Grocery database
func NewGroceryDB(db *sql.DB) *DB {
	return &DB{db}
}

// List retrieves all groceries
func (d *DB) List() ([]Grocery, error) {
	var groceries []Grocery
	query := `
		SELECT id, name, quantity, created_at, updated_at 
		FROM groceries 
		ORDER BY id
	`
	rows, err := d.DB.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	for rows.Next() {
		var g Grocery
		if err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt); err != nil {
			return nil, err
		}
		groceries = append(groceries, g)
	}

	return groceries, nil
}

// Get retrieves a single grocery by ID
func (d *DB) Get(id int) (*Grocery, error) {
	var g Grocery
	query := `
		SELECT id, name, quantity, created_at, updated_at 
		FROM groceries 
		WHERE id = $1
	`
	err := d.DB.QueryRow(query, id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, err
	}
	return &g, nil
}

// Create inserts a new grocery
func (d *DB) Create(name string, quantity int) (*Grocery, error) {
	query := `
		INSERT INTO groceries (name, quantity) 
		VALUES ($1, $2) 
		RETURNING id, name, quantity, created_at, updated_at
	`
	var g Grocery
	err := d.DB.QueryRow(query, name, quantity).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

// Update modifies an existing grocery
func (d *DB) Update(id int, name string, quantity int) error {
	query := `
		UPDATE groceries 
		SET name = $2, quantity = $3, updated_at = NOW() 
		WHERE id = $1
	`
	result, err := d.DB.Exec(query, id, name, quantity)
	if err != nil {
		return err
	}
	if result.RowsAffected() == 0 {
		return fmt.Errorf("grocery with id %d not found", id)
	}
	return nil
}

// Delete removes a grocery by ID
func (d *DB) Delete(id int) error {
	query := `DELETE FROM groceries WHERE id = $1`
	result, err := d.DB.Exec(query, id)
	if err != nil {
		return err
	}
	if result.RowsAffected() == 0 {
		return fmt.Errorf("grocery with id %d not found", id)
	}
	return nil
}

// Migrate applies migrations to the database
func (d *DB) Migrate() error {
	m, err := migrate.New("file://migrations", "file://migrations")
	if err != nil {
		return err
	}
	return m.Migrate(d.DB)
}

