	grocery := Grocery{
		Name:      name,
		Quantity:  quantity,
	}
	if err := db.Create(&grocery).Error; err != nil {
		log.Printf("Failed to create grocery: %v", err)
		return nil, err
	}
	return &grocery, nil
}

func GetGrocery(db *gorm.DB, id uint) (*Grocery, error) {
	var grocery Grocery
	if err := db.Where("id = ?", id).First(&grocery).Error; err != nil {
		if err == gorm.ErrRecordNotFound {
			return nil, nil
		}
		log.Printf("Failed to get grocery: %v", err)
		return nil, err
	}
	return &grocery, nil
}

func ListGroceries(db *gorm.DB) ([]*Grocery, error) {
	var groceries []*Grocery
	if err := db.Find(&groceries).Error; err != nil {
		log.Printf("Failed to list groceries: %v", err)
		return nil, err
	}
	return groceries, nil
}

func UpdateGrocery(db *gorm.DB, id uint, name string, quantity int) error {
	var grocery Grocery
	if err := db.Where("id = ?", id).First(&grocery).Error; err != nil {
		if err == gorm.ErrRecordNotFound {
			return nil
		}
		log.Printf("Failed to update grocery: %v", err)
		return err
	}
	grocery.Name = name
	grocery.Quantity = quantity
	grocery.UpdatedAt = time.Now()
	return db.Save(&grocery).Error
}

func DeleteGrocery(db *gorm.DB, id uint) error {
	var grocery Grocery
	if err := db.Where("id = ?", id).First(&grocery).Error; err != nil {
		if err == gorm.ErrRecordNotFound {
			return nil
		}
		log.Printf("Failed to delete grocery: %v", err)
		return err
	}
	return db.Delete(&grocery, "id = ?", id).Error
}

