package db

import (
	"context"
	"log"
	"time"

	"github.com/google/uuid"
	"gorm.io/gorm"
)

// Grocery represents a grocery item in the database
type Grocery struct {
	ID        uint      `json:"id" gorm:"primaryKey;autoIncrement"`
	Name      string    `json:"name" gorm:"not null"`
	Quantity  int       `json:"quantity" gorm:"not null;default:0"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

// GetAllGroceries retrieves all groceries from the database
func GetAllGroceries(db *gorm.DB) ([]Grocery, error) {
	var groceries []Grocery
	if err := db.Find(&groceries).Error; err != nil {
		return nil, err
	}
	return groceries, nil
}

// GetGroceryByID retrieves a grocery by its ID
func GetGroceryByID(db *gorm.DB, id uint) (*Grocery, error) {
	var grocery Grocery
	if err := db.First(&grocery, id).Error; err != nil {
		return nil, err
	}
	return &grocery, nil
}

// CreateGrocery creates a new grocery in the database
func CreateGrocery(db *gorm.DB, name string, quantity int) (*Grocery, error) {
	grocery := Grocery{
		Name:      name,
		Quantity:  quantity,
		CreatedAt: time.Now(),
		UpdatedAt: time.Now(),
	}
	if err := db.Create(&grocery).Error; err != nil {
		return nil, err
	}
	return &grocery, nil
}

// UpdateGrocery updates an existing grocery in the database
func UpdateGrocery(db *gorm.DB, id uint, name string, quantity int) error {
	var grocery Grocery
	if err := db.First(&grocery, id).Error; err != nil {
		return err
	}
	grocery.Name = name
	grocery.Quantity = quantity
	grocery.UpdatedAt = time.Now()
	if err := db.Save(&grocery).Error; err != nil {
		return err
	}
	return nil
}

// DeleteGrocery deletes a grocery by its ID
func DeleteGrocery(db *gorm.DB, id uint) error {
	if err := db.Delete(&Grocery{}, id).Error; err != nil {
		return err
	}
	return nil
}

// CreateTable creates the groceries table if it doesn't exist
func CreateTable(db *gorm.DB) error {
	return db.AutoMigrate(&Grocery{}).Error
}

