	return &GroceryHandler{db: db}
}

// List handles GET /groceries
func (gh *GroceryHandler) List(w http.ResponseWriter, r *http.Request) {
	groceries, err := db.GetAllGroceries(gh.db)
	if err != nil {
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(groceries)
}

// Get handles GET /groceries/{id}
func (gh *GroceryHandler) Get(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id, err := strconv.Atoi(vars["id"])
	if err != nil {
		http.Error(w, "Invalid ID format", http.StatusBadRequest)
		return
	}

	grocery, err := db.GetGroceryByID(gh.db, uint(id))
	if err != nil {
		if err == gorm.ErrRecordNotFound {
			http.Error(w, "Grocery not found", http.StatusNotFound)
			return
		}
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(grocery)
}

