func (gh *GroceryHandler) Update(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id, err := strconv.Atoi(vars["id"])
	if err != nil {
		http.Error(w, "Invalid ID format", http.StatusBadRequest)
		return
	}

	var req struct {
		Name      string `json:"name"`
		Quantity  int    `json:"quantity"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	err = db.UpdateGrocery(gh.db, uint(id), req.Name, req.Quantity)
	if err != nil {
		http.Error(w, "Failed to update grocery", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{"message": "Grocery updated successfully"})
}

// Delete handles DELETE /groceries/{id}
func (gh *GroceryHandler) Delete(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
