package db

import (
	"database/sql"
	"time"

	"github.com/google/uuid"
)

// Grocery represents a grocery item
type Grocery struct {
	ID        int
	Name      string
	Quantity  int
	CreatedAt time.Time
	UpdatedAt time.Time
}

// GetAll retrieves all groceries
func GetAll(db *sql.DB) ([]Grocery, error) {
	var groceries []Grocery
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries ORDER BY id`
	rows, err := db.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	for rows.Next() {
		var g Grocery
		if err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt); err != nil {
			return nil, err
		}
		groceries = append(groceries, g)
	}

	return groceries, nil
}

// GetByID retrieves a grocery by ID
func GetByID(db *sql.DB, id int) (*Grocery, error) {
	var g Grocery
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1`
	err := db.QueryRow(query, id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, err
	}
	return &g, nil
}

// Create inserts a new grocery
func Create(db *sql.DB, name string, quantity int) (int, error) {
	query := `INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id`
	var id int
	err := db.QueryRow(query, name, quantity).Scan(&id)
	if err != nil {
		return 0, err
	}
	return id, nil
}

// Update modifies an existing grocery
func Update(db *sql.DB, id int, name string, quantity int) error {
	query := `UPDATE groceries SET name = $2, quantity = $3, updated_at = NOW() WHERE id = $1`
	_, err := db.Exec(query, id, name, quantity)
	return err
}

// Delete removes a grocery by ID
func Delete(db *sql.DB, id int) error {
	query := `DELETE FROM groceries WHERE id = $1`
	_, err := db.Exec(query, id)
	return err
}

