package db

import (
	"context"
	"database/sql"
	"fmt"
	"time"

	"github.com/google/uuid"
)

// Grocery represents a grocery item
type Grocery struct {
	ID        int
	Name      string
	Quantity  int
	CreatedAt time.Time
	UpdatedAt time.Time
}

// GetAll retrieves all groceries from the database
func GetAll(ctx context.Context) ([]Grocery, error) {
	var groceries []Grocery
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries ORDER BY id`
	rows, err := db.QueryContext(ctx, query)
	if err != nil {
		return nil, fmt.Errorf("failed to query groceries: %w", err)
	}
	defer rows.Close()

	for rows.Next() {
		var g Grocery
		if err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt); err != nil {
			return nil, fmt.Errorf("failed to scan grocery row: %w", err)
		}
		groceries = append(groceries, g)
	}

	return groceries, nil
}

// GetByID retrieves a single grocery by ID
func GetByID(ctx context.Context, id int) (*Grocery, error) {
	var g Grocery
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1`
	err := db.QueryRowContext(ctx, query, id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, fmt.Errorf("failed to query grocery by ID: %w", err)
	}
	return &g, nil
}

// Create inserts a new grocery into the database
func Create(ctx context.Context, name string, quantity int) (*Grocery, error) {
	query := `INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id, name, quantity, created_at, updated_at`
	var g Grocery
	err := db.QueryRowContext(ctx, query, name, quantity).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return nil, fmt.Errorf("failed to create grocery: %w", err)
	}
	return &g, nil
}

// Update updates an existing grocery by ID
func Update(ctx context.Context, id int, name string, quantity int) (*Grocery, error) {
	query := `UPDATE groceries SET name = $2, quantity = $3, updated_at = NOW() WHERE id = $1 RETURNING id, name, quantity, created_at, updated_at`
	var g Grocery
	err := db.QueryRowContext(ctx, query, id, name, quantity).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, fmt.Errorf("failed to update grocery: %w", err)
	}
	return &g, nil
}

// Delete removes a grocery by ID
func Delete(ctx context.Context, id int) error {
	query := `DELETE FROM groceries WHERE id = $1`
	result, err := db.ExecContext(ctx, query, id)
	if err != nil {
		return fmt.Errorf("failed to delete grocery: %w", err)
	}
	if result.RowsAffected() == 0 {
		return nil
	}
	return nil
}

