package db

import (
	"context"
	"database/sql"
	"log"
	"time"

	"github.com/your-org/your-app/internal/db/schema"
	_ "github.com/lib/pq"
)

// Grocery represents a grocery item
type Grocery struct {
	ID        int
	Name      string
	Quantity  int
	CreatedAt time.Time
	UpdatedAt time.Time
}

// GroceryStore manages grocery operations
type GroceryStore struct {
	DB *sql.DB
}

// NewGroceryStore creates a new GroceryStore
func NewGroceryStore(db *sql.DB) *GroceryStore {
	return &GroceryStore{DB: db}
}

// List retrieves all groceries
func (gs *GroceryStore) List(ctx context.Context) ([]Grocery, error) {
	var groceries []Grocery
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries ORDER BY id`
	rows, err := gs.DB.QueryContext(ctx, query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	for rows.Next() {
		var g Grocery
		if err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt); err != nil {
			return nil, err
		}
		groceries = append(groceries, g)
	}

	return groceries, nil
}

// Get retrieves a grocery by ID
func (gs *GroceryStore) Get(ctx context.Context, id int) (*Grocery, error) {
	var g Grocery
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1`
	err := gs.DB.QueryRowContext(ctx, query, id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, err
	}
	return &g, nil
}

// Create creates a new grocery
func (gs *GroceryStore) Create(ctx context.Context, name string, quantity int) (*Grocery, error) {
	query := `
		INSERT INTO groceries (name, quantity) 
		VALUES ($1, $2) 
		RETURNING id, name, quantity, created_at, updated_at`

	// Use a timestamp for both created_at and updated_at
	now := time.Now()

	// Prepare the values
	values := []interface{}{name, quantity, now, now}

	// Execute the query
	var g Grocery
	err := gs.DB.QueryRowContext(ctx, query, name, quantity).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return nil, err
	}

	// Update the updated_at field to current time
	g.UpdatedAt = now

	return &g, nil
}

// Update updates a grocery by ID
func (gs *GroceryStore) Update(ctx context.Context, id int, name string, quantity int) (*Grocery, error) {
	query := `
		UPDATE groceries 
		SET name = $2, quantity = $3, updated_at = $4 
		WHERE id = $1 
		RETURNING id, name, quantity, created_at, updated_at`

	now := time.Now()

	// Execute the query
	var g Grocery
	err := gs.DB.QueryRowContext(ctx, query, id, name, quantity, now).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, err
	}

	return &g, nil
}

// Delete removes a grocery by ID
func (gs *GroceryStore) Delete(ctx context.Context, id int) error {
	query := `DELETE FROM groceries WHERE id = $1`
	_, err := gs.DB.ExecContext(ctx, query, id)
	return err
}

