func main() {
	// Create a new Fiber app
	app := fiber.New()

	// Set port from environment variable, default to 8080
	port := getPort()
	log.Printf("Server is running on port %s", port)

	// Configure middleware
	app.Use(cors.New(cors.Config{
		Next: func(c *fiber.Ctx) bool {
			return c.Method() == "OPTIONS"
		},
		AllowOrigins: "*",
	}))
	app.Use(logger.New())

	// Setup database
	db := db.NewInMemoryDB() // Replace with actual DB setup
	groceryHandler := handlers.NewGroceryHandler(db.NewGroceryDB(db.DB))

	// Define routes
	app.Get("/groceries", groceryHandler.List)
	app.Get("/groceries/:id", groceryHandler.Get)
	app.Post("/groceries", groceryHandler.Create)
	app.Put("/groceries/:id", groceryHandler.Update)
	app.Delete("/groceries/:id", groceryHandler.Delete)

	// Start server
	log.Printf("Starting server on port %s", port)
	if err := app.Listen(":" + port); err != nil {
		log.Fatal("Failed to start server:", err)
	}
}

// getPort returns the port from environment variable or defaults to 8080
func getPort() string {
	port := "8080"
	if v := os.Getenv("PORT"); v != "" {
