package db

import (
	"database/sql"
	"time"

	"github.com/your-org/your-app/pkg/db"
)

// Grocery represents a grocery item with name and quantity
type Grocery struct {
	ID        int        `db:"id"`
	Name      string     `db:"name"`
	Quantity  int        `db:"quantity"`
	CreatedAt time.Time  `db:"created_at"`
	UpdatedAt time.Time  `db:"updated_at"`
}

// GetAll retrieves all groceries from the database
func GetAll() ([]Grocery, error) {
	var groceries []Grocery
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries ORDER BY id`
	rows, err := db.DB.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	for rows.Next() {
		var g Grocery
		if err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt); err != nil {
			return nil, err
		}
		groceries = append(groceries, g)
	}
	return groceries, nil
}

// GetById retrieves a grocery by its ID
func GetById(id int) (*Grocery, error) {
	var g Grocery
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1`
	err := db.DB.QueryRow(query, id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil // 404 case handled by caller
		}
		return nil, err
	}
	return &g, nil
}

// Create inserts a new grocery into the database
func Create(name string, quantity int) (*Grocery, error) {
	query := `INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id, name, quantity, created_at, updated_at`
	var g Grocery
	err := db.DB.QueryRow(query, name, quantity).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

// Update modifies an existing grocery by ID
func Update(id int, name string, quantity int) error {
	query := `UPDATE groceries SET name = $2, quantity = $3, updated_at = now() WHERE id = $1`
	_, err := db.DB.Exec(query, id, name, quantity)
	return err
}

// Delete removes a grocery by its ID
func Delete(id int) error {
	query := `DELETE FROM groceries WHERE id = $1`
	_, err := db.DB.Exec(query, id)
	return err
}

