}

func ListGroceries(w http.ResponseWriter, r *http.Request) {
	db := db.GetDB()
	groceries, err := db.ListGroceries(db)
	if err != nil {
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}

	response := make([]GroceryResponse, len(groceries))
	for i, g := range groceries {
		response[i] = GroceryResponse{
			ID:        g.ID,
			Name:      g.Name,
			Quantity:  g.Quantity,
			CreatedAt: g.CreatedAt,
			UpdatedAt: g.UpdatedAt,
		}
	}

	json.NewEncoder(w).Encode(response)
}

func GetGrocery(w http.ResponseWriter, r *http.Request) {
	params := mux.Vars(r)
	idStr := params["id"]
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	g := &db.Grocery{ID: id}
	if err := g.Get(db.GetDB()); err != nil {
		if err == sql.ErrNoRows {
			http.Error(w, "Not found", http.StatusNotFound)
		} else {
			http.Error(w, "Internal server error", http.StatusInternalServerError)
		}
		return
	}

	response := GroceryResponse{
		ID:        g.ID,
		Name:      g.Name,
		Quantity:  g.Quantity,
		CreatedAt: g.CreatedAt,
		UpdatedAt: g.UpdatedAt,
	}

	json.NewEncoder(w).Encode(response)
}

func CreateGrocery(w http.ResponseWriter, r *http.Request) {
	var g db.Grocery
	if err := json.NewDecoder(r.Body).Decode(&g); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	if err := g.Create(db.GetDB()); err != nil {
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}

	response := GroceryResponse{
		ID:        g.ID,
		Name:      g.Name,
		Quantity:  g.Quantity,
		CreatedAt: g.CreatedAt,
		UpdatedAt: g.UpdatedAt,
	}

	json.NewEncoder(w).Encode(response)
}

func UpdateGrocery(w http.ResponseWriter, r *http.Request) {
	params := mux.Vars(r)
	idStr := params["id"]
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	var g db.Grocery
	if err := json.NewDecoder(r.Body).Decode(&g); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	g.ID = id
	if err := g.Update(db.GetDB()); err != nil {
		if err == sql.ErrNoRows {
			http.Error(w, "Not found", http.StatusNotFound)
		} else {
			http.Error(w, "Internal server error", http.StatusInternalServerError)
		}
		return
	}

	response := GroceryResponse{
		ID:        g.ID,
		Name:      g.Name,
		Quantity:  g.Quantity,
		CreatedAt: g.CreatedAt,
		UpdatedAt: g.UpdatedAt,
	}

	json.NewEncoder(w).Encode(response)
}

