		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(groceries)
}

func createGrocery(w http.ResponseWriter, r *http.Request) {
	var input struct {
		Name     string `json:"name"`
		Quantity int    `json:"quantity"`
	}

	if err := json.NewDecoder(r.Body).Decode(&input); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	grocery, err := db.CreateGrocery(input.Name, input.Quantity)
	if err != nil {
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(grocery)
}

func parseID(path string) int {
	// Simple ID parsing - would need proper routing in a real app
	id := 0
	fmt.Sscanf(path, "/groceries/%d", &id)
	return id
