package handlers

import (
	"encoding/json"
	"net/http"
	"strconv"

	"database/sql"
	"github.com/gorilla/mux"
)

type GroceryResponse struct {
	ID          int       `json:"id"`
	Name        string    `json:"name"`
	Quantity    int       `json:"quantity"`
	CreatedAt   string    `json:"created_at"`
	UpdatedAt   string    `json:"updated_at"`
}

func GetGroceries(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		rows, err := db.Query("SELECT id, name, quantity, created_at, updated_at FROM groceries")
		if err != nil {
			http.Error(w, "Internal server error", http.StatusInternalServerError)
			return
		}
		defer rows.Close()

		var groceries []GroceryResponse
		for rows.Next() {
			var g GroceryResponse
			if err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt); err != nil {
				http.Error(w, "Internal server error", http.StatusInternalServerError)
				return
			}
			groceries = append(groceries, g)
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(groceries)
	}
}

func GetGrocery(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		params := mux.Vars(r)
		idStr := params["id"]
		id, err := strconv.Atoi(idStr)
		if err != nil {
			http.Error(w, "Invalid ID", http.StatusBadRequest)
			return
		}

		var g GroceryResponse
		if err := db.QueryRow("SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1", id).Scan(
			&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt,
		); err != nil {
			if err == sql.ErrNoRows {
				http.Error(w, "Grocery not found", http.StatusNotFound)
			} else {
				http.Error(w, "Internal server error", http.StatusInternalServerError)
			}
			return
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(g)
	}
}

func CreateGrocery(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			Name     string `json:"name"`
			Quantity int    `json:"quantity"`
		}

		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			http.Error(w, "Invalid request body", http.StatusBadRequest)
			return
		}

		if req.Name == "" {
			http.Error(w, "Name is required", http.StatusBadRequest)
			return
		}

		var id int
		if err := db.QueryRow("INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id", req.Name, req.Quantity).Scan(&id); err != nil {
			http.Error(w, "Internal server error", http.StatusInternalServerError)
			return
		}

		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(map[string]int{"id": id})
	}
}

func UpdateGrocery(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		params := mux.Vars(r)
		idStr := params["id"]
		id, err := strconv.Atoi(idStr)
		if err != nil {
			http.Error(w, "Invalid ID", http.StatusBadRequest)
			return
		}

		var req struct {
			Name     string `json:"name"`
			Quantity int    `json:"quantity"`
		}

		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			http.Error(w, "Invalid request body", http.StatusBadRequest)
			return
		}

		if req.Name == "" && req.Quantity == 0 {
			http.Error(w, "No fields to update", http.StatusBadRequest)
			return
		}

		var updates []string
		var args []interface{}
		argNum := 1

		if req.Name != "" {
			updates = append(updates, "name = $"+strconv.Itoa(argNum))
			args = append(args, req.Name)
			argNum++
		}

		if req.Quantity != 0 {
			updates = append(updates, "quantity = $"+strconv.Itoa(argNum))
			args = append(args, req.Quantity)
			argNum++
		}

		args = append(args, id)

		query := "UPDATE groceries SET " + strings.Join(updates, ", ") + " WHERE id = $"+strconv.Itoa(argNum)
		_, err = db.Exec(query, args...)
		if err != nil {
			http.Error(w, "Internal server error", http.StatusInternalServerError)
			return
		}

		var g GroceryResponse
		if err := db.QueryRow("SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1", id).Scan(
			&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt,
		); err != nil {
			if err == sql.ErrNoRows {
				http.Error(w, "Grocery not found", http.StatusNotFound)
			} else {
				http.Error(w, "Internal server error", http.StatusInternalServerError)
			}
			return
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(g)
	}
}

func DeleteGrocery(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		params := mux.Vars(r)
		idStr := params["id"]
		id, err := strconv.Atoi(idStr)
		if err != nil {
			http.Error(w, "Invalid ID", http.StatusBadRequest)
			return
		}

		if _, err := db.Exec("DELETE FROM groceries WHERE id = $1", id); err != nil {
			http.Error(w, "Internal server error", http.StatusInternalServerError)
			return
		}

		w.WriteHeader(http.StatusNoContent)
	}
}

