package db

import (
	"database/sql"
	"fmt"
)

type Grocery struct {
	ID        int     `json:"id"`
	Name      string  `json:"name"`
	Quantity  int     `json:"quantity"`
	CreatedAt string  `json:"created_at"`
	UpdatedAt string  `json:"updated_at"`
}

func CreateGrocery(db *sql.DB, name string, quantity int) (*Grocery, error) {
	var id int
	err := db.QueryRow("INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id", name, quantity).Scan(&id)
	if err != nil {
		return nil, err
	}

	return GetGroceryByID(db, id)
}

func GetGroceryByID(db *sql.DB, id int) (*Grocery, error) {
	var g Grocery
	err := db.QueryRow("SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1", id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return nil, fmt.Errorf("grocery not found")
	}
	return &g, nil
}

func GetGroceries(db *sql.DB) ([]*Grocery, error) {
	rows, err := db.Query("SELECT id, name, quantity, created_at, updated_at FROM groceries")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		var g Grocery
		if err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt); err != nil {
			return nil, err
		}
		groceries = append(groceries, &g)
	}
	return groceries, nil
}

func UpdateGrocery(db *sql.DB, id int, name string, quantity int) (*Grocery, error) {
	_, err := db.Exec("UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3", name, quantity, id)
	if err != nil {
