type Grocery struct {
	ID        int       `db:"id"`
	Name      string    `db:"name"`
	Quantity  int       `db:"quantity"`
	CreatedAt time.Time `db:"created_at"`
	UpdatedAt time.Time `db:"updated_at"`
}

func (g *Grocery) Create(db *sql.DB) error {
	err := db.QueryRow("INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id", g.Name, g.Quantity).Scan(&g.ID)
	if err != nil {
		return err
	}
	return nil
}

func (g *Grocery) Get(db *sql.DB) error {
	err := db.QueryRow("SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1", g.ID).Scan(
		&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return err
	}
	return nil
}

func (g *Grocery) Update(db *sql.DB) error {
	res, err := db.Exec("UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3", g.Name, g.Quantity, g.ID)
	if err != nil {
		return err
	}
	rows, _ := res.RowsAffected()
	if rows == 0 {
		return sql.ErrNoRows
	}
	return nil
}

func (g *Grocery) Delete(db *sql.DB) error {
	res, err := db.Exec("DELETE FROM groceries WHERE id = $1", g.ID)
	if err != nil {
		return err
	}
	rows, _ := res.RowsAffected()
	if rows == 0 {
		return sql.ErrNoRows
	}
	return nil
}

func ListGroceries(db *sql.DB) ([]*Grocery, error) {
	rows, err := db.Query("SELECT id, name, quantity, created_at, updated_at FROM groceries")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		g := &Grocery{}
		err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
