	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

func ListGroceries(w http.ResponseWriter, r *http.Request) {
	db := db.GetDB()
	groceries, err := db.ListGroceries(db)
	if err != nil {
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}

	response := make([]GroceryResponse, len(groceries))
	for i, g := range groceries {
		response[i] = GroceryResponse{
			ID:        g.ID,
			Name:      g.Name,
			Quantity:  g.Quantity,
			CreatedAt: g.CreatedAt,
			UpdatedAt: g.UpdatedAt,
		}
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(response)
}

func GetGrocery(w http.ResponseWriter, r *http.Request) {
	idStr := r.PathValue("id")
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	g := &db.Grocery{ID: id}
	if err := g.Get(db.GetDB()); err != nil {
		if err == sql.ErrNoRows {
			http.Error(w, "Not found", http.StatusNotFound)
		} else {
			http.Error(w, "Internal server error", http.StatusInternalServerError)
		}
		return
	}

	response := GroceryResponse{
		ID:        g.ID,
		Name:      g.Name,
		Quantity:  g.Quantity,
		CreatedAt: g.CreatedAt,
		UpdatedAt: g.UpdatedAt,
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(response)
}

func CreateGrocery(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Name     string `json:"name"`
		Quantity int    `json:"quantity"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	g := &db.Grocery{Name: req.Name, Quantity: req.Quantity}
	if err := g.Create(db.GetDB()); err != nil {
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}

	response := GroceryResponse{
		ID:        g.ID,
		Name:      g.Name,
		Quantity:  g.Quantity,
		CreatedAt: g.CreatedAt,
		UpdatedAt: g.UpdatedAt,
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(response)
}

func UpdateGrocery(w http.ResponseWriter, r *http.Request) {
	idStr := r.PathValue("id")
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	var req struct {
		Name     string `json:"name"`
		Quantity int    `json:"quantity"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	g := &db.Grocery{ID: id, Name: req.Name, Quantity: req.Quantity}
	if err := g.Update(db.GetDB()); err != nil {
		if err == sql.ErrNoRows {
			http.Error(w, "Not found", http.StatusNotFound)
		} else {
			http.Error(w, "Internal server error", http.StatusInternalServerError)
		}
		return
	}

	response := GroceryResponse{
		ID:        g.ID,
		Name:      g.Name,
		Quantity:  g.Quantity,
		CreatedAt: g.CreatedAt,
		UpdatedAt: g.UpdatedAt,
	}

	json.NewEncoder(w).Encode(response)
}

func DeleteGrocery(w http.ResponseWriter, r *http.Request) {
	idStr := r.PathValue("id")
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	g := &db.Grocery{ID: id}
	if err := g.Delete(db.GetDB()); err != nil {
		if err == sql.ErrNoRows {
			http.Error(w, "Not found", http.StatusNotFound)
		} else {
			http.Error(w, "Internal server error", http.StatusInternalServerError)
		}
		return
	}

	w.WriteHeader(http.StatusNoContent)
}

