	row := db.QueryRow(query, name, quantity)
	var g Grocery
	err := row.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return nil, fmt.Errorf("error inserting grocery: %w", err)
	}
	return &g, nil
}

func GetGrocery(db *sql.DB, id int64) (*Grocery, error) {
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1`
	var g Grocery
	err := db.QueryRow(query, id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, fmt.Errorf("grocery not found")
		}
		return nil, fmt.Errorf("error fetching grocery: %w", err)
	}
	return &g, nil
}

