	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		var g Grocery
		err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
		if err != nil {
			return nil, fmt.Errorf("error scanning grocery: %w", err)
		}
		groceries = append(groceries, &g)
	}
	return groceries, nil
}

func UpdateGrocery(db *sql.DB, id int64, name string, quantity int) (*Grocery, error) {
	query := `UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3 RETURNING id, name, quantity, created_at, updated_at`
	row := db.QueryRow(query, name, quantity, id)
	var g Grocery
	err := row.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return nil, fmt.Errorf("error updating grocery: %w", err)
	}
	return &g, nil
