	}

	// Test create endpoint
	createBody := `{"name": "Milk", "quantity": 2}`
	resp = performRequest(r, "POST", "/groceries", []byte(createBody))
	if resp.Code != http.StatusCreated {
		t.Errorf("Expected 201, got %d", resp.Code)
	}

	// Test get by ID
	resp = performRequest(r, "GET", "/groceries/1", nil)
	if resp.Code != http.StatusOK {
		t.Errorf("Expected 200, got %d", resp.Code)
	}

	// Test update
	updateBody := `{"name": "Cheese", "quantity": 1}`
	resp = performRequest(r, "PUT", "/groceries/1", []byte(updateBody))
	if resp.Code != http.StatusOK {
		t.Errorf("Expected 200, got %d", resp.Code)
	}

	// Test delete
	resp = performRequest(r, "DELETE", "/groceries/1", nil)
	if resp.Code != http.StatusOK {
		t.Errorf("Expected 200, got %d", resp.Code)
	}
}

func performRequest(r *gin.Engine, method, path string, body []byte) *httptest.ResponseRecorder {
	w := httptest.NewRecorder()
	req, _ := http.NewRequest(method, path, bytes.NewBuffer(body))
	r.ServeHTTP(w, req)
	return w
}

