package db

import (
	"database/sql"
	"time"
)

type Grocery struct {
	ID        int       `db:"id"`
	Name      string    `db:"name"`
	Quantity  int       `db:"quantity"`
	CreatedAt time.Time `db:"created_at"`
	UpdatedAt time.Time `db:"updated_at"`
}

func (g *Grocery) Create(db *sql.DB) error {
	query := `INSERT INTO groceries (name, quantity) VALUES (?, ?)`
	result, err := db.Exec(query, g.Name, g.Quantity)
	if err != nil {
		return err
	}
	id, _ := result.LastInsertId()
	g.ID = int(id)
	return nil
}

func GetAllGroceries(db *sql.DB) ([]*Grocery, error) {
	rows, err := db.Query("SELECT id, name, quantity, created_at, updated_at FROM groceries")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		grocery := &Grocery{}
		err := rows.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
		if err != nil {
			return nil, err
		}
		groceries = append(groceries, grocery)
	}
	return groceries, nil
}

func GetGroceryByID(db *sql.DB, id int) (*Grocery, error) {
	grocery := &Grocery{}
	err := db.QueryRow("SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = ?", id).
		Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return grocery, nil
}

func (g *Grocery) Update(db *sql.DB) error {
	_, err := db.Exec("UPDATE groceries SET name = ?, quantity = ? WHERE id = ?", g.Name, g.Quantity, g.ID)
	return err
}

func (g *Grocery) Delete(db *sql.DB) error {
	_, err := db.Exec("DELETE FROM groceries WHERE id = ?", g.ID)
	return err
}

