	return func(c *gin.Context) {
		var req GroceryRequest
		if err := c.BindJSON(&req); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid input"})
			return
		}

		grocery := &Grocery{Name: req.Name, Quantity: req.Quantity}
		if err := grocery.Create(db); err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Creation failed"})
			return
		}

		c.JSON(http.StatusCreated, grocery)
	}
}

func GetGrocery(db *sql.DB) gin.HandlerFunc {
	return func(c *gin.Context) {
		idStr := c.Param("id")
		id, err := strconv.Atoi(idStr)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid ID"})
			return
		}

		grocery, err := db.GetGroceryByID(db, id)
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Database error"})
			return
		}
		if grocery == nil {
			c.JSON(http.StatusNotFound, gin.H{"error": "Grocery not found"})
			return
		}

		c.JSON(http.StatusOK, grocery)
	}
}

func UpdateGrocery(db *sql.DB) gin.HandlerFunc {
	return func(c *gin.Context) {
		idStr := c.Param("id")
		id, err := strconv.Atoi(idStr)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid ID"})
			return
		}

		var req GroceryRequest
		if err := c.BindJSON(&req); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid input"})
			return
		}

		grocery := &Grocery{ID: id, Name: req.Name, Quantity: req.Quantity}
		if err := grocery.Update(db); err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Update failed"})
			return
		}

		c.JSON(http.StatusOK, grocery)
	}
}

func DeleteGrocery(db *sql.DB) gin.HandlerFunc {
	return func(c *gin.Context) {
		idStr := c.Param("id")
		id, err := strconv.Atoi(idStr)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid ID"})
			return
		}

		grocery := &Grocery{ID: id}
		if err := grocery.Delete(db); err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Deletion failed"})
			return
		}

		c.JSON(http.StatusOK, gin.H{"message": "Grocery deleted"})
	}
}

