package db

import (
	"database/sql"
	"time"
)

type Grocery struct {
	ID        int       `db:"id"`
	Name      string    `db:"name"`
	Quantity  int       `db:"quantity"`
	CreatedAt time.Time `db:"created_at"`
	UpdatedAt time.Time `db:"updated_at"`
}

func (g *Grocery) Create(db *sql.DB) error {
	query := `INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id`
	err := db.QueryRow(query, g.Name, g.Quantity).Scan(&g.ID)
	return err
}

func (g *Grocery) Get(db *sql.DB) error {
	query := `SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1`
	err := db.QueryRow(query, g.ID).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	return err
}

func (g *Grocery) Update(db *sql.DB) error {
	query := `UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3`
	_, err := db.Exec(query, g.Name, g.Quantity, g.ID)
	return err
}

func (g *Grocery) Delete(db *sql.DB) error {
	query := `DELETE FROM groceries WHERE id = $1`
	_, err := db.Exec(query, g.ID)
	return err
}

func ListGroceries(db *sql.DB) ([]*Grocery, error) {
	rows, err := db.Query(`SELECT id, name, quantity, created_at, updated_at FROM groceries`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		g := &Grocery{}
		err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
		if err != nil {
			return nil, err
		}
		groceries = append(groceries, g)
	}
	return groceries, nil
}

