func TestGroceryCRUD(t *testing.T) {
	db := setupTestDB()
	defer db.Close()

	t.Run("Create", func(t *testing.T) {
		g := &Grocery{Name: "Milk", Quantity: 2}
		err := g.Create(db)
		require.NoError(t, err)
		require.NotZero(t, g.ID)
	})

	t.Run("Get", func(t *testing.T) {
		g := &Grocery{Name: "Eggs", Quantity: 12}
		err := g.Create(db)
		require.NoError(t, err)

		g2 := &Grocery{ID: g.ID}
		err = g2.Get(db)
		require.NoError(t, err)
		require.Equal(t, g.Name, g2.Name)
		require.Equal(t, g.Quantity, g2.Quantity)
	})

	t.Run("Update", func(t *testing.T) {
		g := &Grocery{Name: "Bread", Quantity: 1}
		err := g.Create(db)
		require.NoError(t, err)

		g.Quantity = 2
		err = g.Update(db)
		require.NoError(t, err)

		g2 := &Grocery{ID: g.ID}
		err = g2.Get(db)
		require.NoError(t, err)
		require.Equal(t, 2, g2.Quantity)
	})

	t.Run("Delete", func(t *testing.T) {
		g := &Grocery{Name: "Butter", Quantity: 1}
		err := g.Create(db)
		require.NoError(t, err)

		err = g.Delete(db)
		require.NoError(t, err)

		g2 := &Grocery{ID: g.ID}
		err = g2.Get(db)
		require.Error(t, err)
	})

	t.Run("List", func(t *testing.T) {
		// Create two items
		g1 := &Grocery{Name: "Cheese", Quantity: 3}
		err := g1.Create(db)
		require.NoError(t, err)

		g2 := &Grocery{Name: "Yogurt", Quantity: 5}
		err = g2.Create(db)
		require.NoError(t, err)

		groceries, err := ListGroceries(db)
		require.NoError(t, err)
		require.Len(t, groceries, 2)
	})
}

