package handlers

import (
	"encoding/json"
	"net/http"
	"strconv"

	"github.com/grocery-service/db"
)

type GroceryRequest struct {
	Name     string `json:"name"`
	Quantity int    `json:"quantity"`
}

type GroceryResponse struct {
	ID        int    `json:"id"`
	Name      string `json:"name"`
	Quantity  int    `json:"quantity"`
	CreatedAt string `json:"created_at"`
	UpdatedAt string `json:"updated_at"`
}

func NewGroceryResponse(g *db.Grocery) *GroceryResponse {
	return &GroceryResponse{
		ID:        g.ID,
		Name:      g.Name,
		Quantity:  g.Quantity,
		CreatedAt: g.CreatedAt.Format(time.RFC3339),
		UpdatedAt: g.UpdatedAt.Format(time.RFC3339),
	}
}

func (h *Handler) GetAllGroceries(w http.ResponseWriter, r *http.Request) {
	groceries, err := h.DB.GetAllGroceries()
	if err != nil {
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	response := make([]*GroceryResponse, len(groceries))
	for i, g := range groceries {
		response[i] = NewGroceryResponse(g)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(response)
}

func (h *Handler) GetGroceryByID(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.URL.Path[len("/groceries/"):])
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	grocery, err := h.DB.GetGroceryByID(id)
	if err != nil {
		if err == sql.ErrNoRows {
			http.Error(w, "Grocery not found", http.StatusNotFound)
			return
		}
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	response := NewGroceryResponse(grocery)
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(response)
}

func (h *Handler) CreateGrocery(w http.ResponseWriter, r *http.Request) {
	var req GroceryRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	grocery, err := h.DB.CreateGrocery(req.Name, req.Quantity)
	if err != nil {
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	response := NewGroceryResponse(grocery)
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(response)
}

func (h *Handler) UpdateGrocery(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.URL.Path[len("/groceries/"):])
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	var req GroceryRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	grocery, err := h.DB.UpdateGrocery(id, req.Name, req.Quantity)
	if err != nil {
		if err == sql.ErrNoRows {
			http.Error(w, "Grocery not found", http.StatusNotFound)
			return
		}
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	response := NewGroceryResponse(grocery)
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(response)
}

func (h *Handler) DeleteGrocery(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.URL.Path[len("/groceries/"):])
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	err = h.DB.DeleteGrocery(id)
	if err != nil {
		if err == sql.ErrNoRows {
			http.Error(w, "Grocery not found", http.StatusNotFound)
			return
		}
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusNoContent)
}

