	if err != nil {
		t.Fatal(err)
	}

	if grocery.Name != "Apples" {
		t.Errorf("Expected name 'Apples', got '%s'", grocery.Name)
	}

	if grocery.Quantity != 5 {
		t.Errorf("Expected quantity 5, got %d", grocery.Quantity)
	}

	// Test getting all groceries
	groceries, err := GetAllGroceries(db)
	if err != nil {
		t.Fatal(err)
	}

	if len(groceries) != 1 {
		t.Errorf("Expected 1 grocery, got %d", len(groceries))
	}

	// Test getting by ID
	groceryByID, err := GetGroceryByID(db, grocery.ID)
	if err != nil {
		t.Fatal(err)
	}

	if groceryByID.Name != "Apples" {
		t.Errorf("Expected name 'Apples', got '%s'", groceryByID.Name)
	}

	// Test updating
	updatedGrocery, err := UpdateGrocery(db, grocery.ID, "Bananas", 10)
	if err != nil {
		t.Fatal(err)
	}

	if updatedGrocery.Name != "Bananas" {
		t.Errorf("Expected name 'Bananas', got '%s'", updatedGrocery.Name)
	}

	if updatedGrocery.Quantity != 10 {
		t.Errorf("Expected quantity 10, got %d", updatedGrocery.Quantity)
	}

	// Test deleting
	err = DeleteGrocery(db, grocery.ID)
	if err != nil {
		t.Fatal(err)
	}

	groceries, err = GetAllGroceries(db)
	if err != nil {
		t.Fatal(err)
	}

	if len(groceries) != 0 {
		t.Errorf("Expected 0 groceries after deletion, got %d", len(groceries))
	}
}

