	)`)
	if err != nil {
		t.Fatalf("failed to create table: %v", err)
	}

	// Test CreateGrocery
	grocery, err := CreateGrocery(db, "Apples", 5)
	if err != nil {
		t.Fatalf("failed to create grocery: %v", err)
	}

	if grocery.Name != "Apples" {
		t.Errorf("expected name 'Apples', got '%s'", grocery.Name)
	}

	if grocery.Quantity != 5 {
		t.Errorf("expected quantity 5, got %d", grocery.Quantity)
	}

	// Test GetAllGroceries
	groceries, err := GetAllGroceries(db)
	if err != nil {
		t.Fatalf("failed to get all groceries: %v", err)
	}

	if len(groceries) != 1 {
		t.Errorf("expected 1 grocery, got %d", len(groceries))
	}

	// Test GetGroceryByID
