	if err != nil {
		t.Fatalf("failed to get grocery by ID: %v", err)
	}

	if found.Name != "Apples" {
		t.Errorf("expected name 'Apples', got '%s'", found.Name)
	}

	// Test UpdateGrocery
	updated, err := UpdateGrocery(db, grocery.ID, "Bananas", 10)
	if err != nil {
		t.Fatalf("failed to update grocery: %v", err)
	}

	if updated.Name != "Bananas" {
		t.Errorf("expected name 'Bananas', got '%s'", updated.Name)
	}

	if updated.Quantity != 10 {
		t.Errorf("expected quantity 10, got %d", updated.Quantity)
	}

	// Test DeleteGrocery
	err = DeleteGrocery(db, grocery.ID)
	if err != nil {
		t.Fatalf("failed to delete grocery: %v", err)
	}

	_, err = GetGroceryByID(db, grocery.ID)
	if err == nil {
		t.Errorf("expected error when getting deleted grocery")
	}

	// Test that table has no rows now
	groceries, err = GetAllGroceries(db)
	if err != nil {
		t.Fatalf("failed to get all groceries: %v", err)
	}

	if len(groceries) != 0 {
		t.Errorf("expected 0 groceries, got %d", len(groceries))
	}
}

