package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"

	_ "github.com/mattn/go-sqlite3"
	"github.com/grocery-service/db"
	"github.com/grocery-service/handlers"
)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	db, err := sql.Open("sqlite3", "./groceries.db")
	if err != nil {
		log.Fatal("Failed to open database:", err)
	}
	defer db.Close()

	_, err = db.Exec("CREATE TABLE IF NOT EXISTS groceries (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP)")
	if err != nil {
		log.Fatal("Failed to create table:", err)
	}

	h := &handlers.Handler{DB: &db}

	mux := http.NewServeMux()
	mux.HandleFunc("GET /groceries", h.GetAllGroceries)
	mux.HandleFunc("GET /groceries/{id}", h.GetGroceryByID)
	mux.HandleFunc("POST /groceries", h.CreateGrocery)
	mux.HandleFunc("PUT /groceries/{id}", h.UpdateGrocery)
	mux.HandleFunc("DELETE /groceries/{id}", h.DeleteGrocery)

	log.Printf("Server starting on port %s", port)
	log.Fatal(http.ListenAndServe(":"+port, mux))
}

