package db

import (
	"database/sql"
	"time"
)

type Grocery struct {
	ID          int       `json:"id"`
	Name        string    `json:"name"`
	Quantity    int       `json:"quantity"`
	CreatedAt   time.Time `json:"created_at"`
	UpdatedAt   time.Time `json:"updated_at"`
}

func GetAllGroceries(db *sql.DB) ([]Grocery, error) {
	rows, err := db.Query("SELECT id, name, quantity, created_at, updated_at FROM groceries ORDER BY id")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []Grocery
	for rows.Next() {
		var g Grocery
		err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
		if err != nil {
			return nil, err
		}
		groceries = append(groceries, g)
	}

	return groceries, nil
}

func GetGroceryByID(db *sql.DB, id int) (*Grocery, error) {
	var g Grocery
	err := db.QueryRow("SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = ?", id).
		Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

func CreateGrocery(db *sql.DB, name string, quantity int) (*Grocery, error) {
	result, err := db.Exec("INSERT INTO groceries (name, quantity) VALUES (?, ?)", name, quantity)
	if err != nil {
		return nil, err
	}

	id, err := result.LastInsertId()
	if err != nil {
		return nil, err
	}

	return GetGroceryByID(db, int(id))
}

func UpdateGrocery(db *sql.DB, id int, name string, quantity int) (*Grocery, error) {
	_, err := db.Exec("UPDATE groceries SET name = ?, quantity = ? WHERE id = ?", name, quantity, id)
	if err != nil {
		return nil, err
	}

	return GetGroceryByID(db, id)
}

func DeleteGrocery(db *sql.DB, id int) error {
	_, err := db.Exec("DELETE FROM groceries WHERE id = ?", id)
	return err
}

