package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"

	"github.com/grocery-api/db"
	"github.com/grocery-api/handlers"
)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	db, err := sql.Open("sqlite3", "./groceries.db")
	if err != nil {
		log.Fatal("Failed to open database:", err)
	}
	defer db.Close()

	_, err = db.Exec(`CREATE TABLE IF NOT EXISTS groceries (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		name TEXT NOT NULL,
		quantity INTEGER NOT NULL DEFAULT 0,
		created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
		updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
	)`)
	if err != nil {
		log.Fatal("Failed to create table:", err)
	}

	database := &db.DB{DB: db}
	groceriesHandler := handlers.NewGroceriesHandler(database)

	mux := http.NewServeMux()
	mux.HandleFunc("GET /groceries", groceriesHandler.List)
	mux.HandleFunc("GET /groceries/{id}", groceriesHandler.Get)
	mux.HandleFunc("POST /groceries", groceriesHandler.Create)
	mux.HandleFunc("PUT /groceries/{id}", groceriesHandler.Update)
	mux.HandleFunc("DELETE /groceries/{id}", groceriesHandler.Delete)

	log.Printf("Server starting on port %s", port)
	err = http.ListenAndServe(":"+port, mux)
	if err != nil {
		log.Fatal("Server failed to start:", err)
	}
}

