		err := rows.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
		if err != nil {
			return nil, err
		}
		groceries = append(groceries, grocery)
	}

	return groceries, rows.Err()
}

func (db *DB) GetGrocery(id int) (*Grocery, error) {
	grocery := Grocery{}
	err := db.QueryRow("SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1", id).
		Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &grocery, nil
}

func (db *DB) CreateGrocery(name string, quantity int) (*Grocery, error) {
	grocery := Grocery{}
	err := db.QueryRow("INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id, name, quantity, created_at, updated_at",
		name, quantity).
		Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &grocery, nil
}

